  // Try to create the bucket with snapshots enabled (with retries)
  const maxAttempts = 12;
  const retryDelay = 10_000; // 10 seconds
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    console.log(`Creating bucket with snapshots enabled (attempt ${attempt}/${maxAttempts})...`);
    const createResult = await createBucket(bucketName, {
      enableSnapshot: true,
      config: tigrisConfig,
    });
    if (!createResult.error) {
      console.log(`Bucket created: snapshotEnabled=${createResult.data.isSnapshotEnabled}`);
      return;
    }
    const msg = createResult.error.message ?? "";
    console.warn(`Attempt ${attempt} failed: ${msg}`);
    if (attempt < maxAttempts) {
      console.log(`Waiting ${retryDelay / 1000}s before retry...`);
      await sleep(retryDelay);
    } else {
      throw new Error(`Failed to create bucket after ${maxAttempts} attempts: ${msg}`);
    }
  }
}

async function main() {
  // Step 1: Read trial ID and construct source bucket name
  const trialIdRaw = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const trialIdNormalized = trialIdRaw.toLowerCase().replace(/[^a-z0-9.\-]/g, "-");
  const sourceBucketName = `harbor-seeded-${trialIdNormalized}`;
  console.log(`Source bucket: ${sourceBucketName}`);

  // Ensure the bucket exists with snapshots enabled
  await ensureBucketWithSnapshots(sourceBucketName);

  // Step 2: Upload data files to source bucket using AWS SDK v3
  const s3 = new S3Client({
    region: "REDACTED",
    endpoint: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
    forcePathStyle: false,
  });

  const files = ["a.txt", "b.txt", "c.txt"];
  for (const filename of files) {
    const content = await readFile(join(PROJECT_DIR, "data", filename));
    await s3.send(
      new PutObjectCommand({
        Bucket: sourceBucketName,
        Key: filename,
        Body: content,
      })
    );
    console.log(`Uploaded ${filename} to ${sourceBucketName}`);
  }

  // Steps 3-5: createForks, write forks.json, teardownForks
  let forkSet: Forks | undefined;
  try {
    const { data, error } = await createForks(sourceBucketName, 2, {
      prefix: "eval-dispatch",
      credentials: { role: "ReadOnly" },
    });

    if (error) {
      throw error;
    }

    forkSet = data;
    console.log(`Created forks: ${forkSet.forks.map((f) => f.bucket).join(", ")}`);

    // Step 4: Write forks.json BEFORE teardown
    const forkNames = forkSet.forks.map((f) => f.bucket);
    const forksJson = JSON.stringify({ forks: forkNames }, null, 2);
    await writeFile(join(PROJECT_DIR, "forks.json"), forksJson, "utf-8");
    console.log(`Written forks.json: ${forksJson}`);
  } finally {
    // Step 5: Teardown forks
    if (forkSet) {
      const { error: teardownError } = await teardownForks(forkSet);
      if (teardownError) {
        console.error("teardownForks error:", teardownError);
      } else {
        console.log("Forks torn down successfully.");
      }
    }
  }
}

main().then(() => {
  process.exit(0);
}).catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
